// Consolidate emails and calendar events into structured format
const allItems = $input.all();

// Separate emails and calendar events
const emails = [];
const calendarEvents = [];

for (const item of allItems) {
  const data = item.json;

  // Check if it's an email (has 'from' and 'subject' fields)
  if (data.from && data.subject) {
    emails.push({
      from: data.from?.value?.[0]?.address || data.from || 'Unknown',
      fromName: data.from?.value?.[0]?.name || '',
      subject: data.subject || 'No Subject',
      date: data.date || '',
      // REMOVED TRUNCATION: Captures the full text body
      fullText: data.text || data.textPlain || ''
    });
  }

  // Check if it's a calendar event (has 'summary' and 'start' fields)
  if (data.summary && (data.start || data.startTime)) {
    const startTime = data.start?.dateTime || data.startTime || data.start?.date || '';
    const endTime = data.end?.dateTime || data.endTime || data.end?.date || '';

    calendarEvents.push({
      title: data.summary || 'Untitled Event',
      startTime: startTime,
      endTime: endTime,
      location: data.location || '',
      // REMOVED TRUNCATION: Captures the full description
      description: data.description || '',
      attendees: data.attendees?.map(a => a.email).join(', ') || ''
    });
  }
}

// Sort calendar events by start time
calendarEvents.sort((a, b) => new Date(a.startTime) - new Date(b.startTime));

return [{
  json: {
    emailCount: emails.length,
    eventCount: calendarEvents.length,
    emails: emails,
    calendarEvents: calendarEvents,
    generatedAt: new Date().toISOString()
  }
}];

// Format the briefing for Slack
const inputData = $input.first().json;
const consolidatedData = $('Consolidate Data').first().json;

// Extract the AI-generated briefing
let briefing = '';

try {
  // Handle different response structures from OpenAI node
  if (inputData.message?.content) {
    briefing = inputData.message.content;
  } else if (inputData.text) {
    briefing = inputData.text;
  } else if (inputData.content) {
    briefing = inputData.content;
  } else if (typeof inputData === 'string') {
    briefing = inputData;
  } else {
    briefing = JSON.stringify(inputData);
  }
} catch (error) {
  briefing = 'Error generating briefing. Please check the workflow.';
}

// Get current date formatted nicely
const today = new Date();
const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const formattedDate = today.toLocaleDateString('en-US', dateOptions);

// Create Slack-formatted message
const slackMessage = `*🌅 Daily Executive Briefing*\n*${formattedDate}*\n\n---\n\n${briefing}\n\n---\n_Generated at ${today.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })} • ${consolidatedData.emailCount} emails • ${consolidatedData.eventCount} events_`;

return [{
  json: {
    slackMessage: slackMessage,
    rawBriefing: briefing,
    metadata: {
      emailCount: consolidatedData.emailCount,
      eventCount: consolidatedData.eventCount,
      generatedAt: today.toISOString()
    }
  }
}];
